 ap=argparse.ArgumentParser();ap.add_argument('--cell',required=True);a=ap.parse_args();d=R/'artifacts/analog_asic/layout'/a.cell;dest=d/'independent_gds_exact_connectivity_v1.json';assert not dest.exists();fq=json.loads((d/'flat_cap_qualification.json').read_text());top=a.cell;native=R/'artifacts/analog_asic/verification/gds_roundtrip'/a.cell/'roundtrip.spice';source,sm=compact(native.read_text(),top);reference,rm=compact((d/'reference.spice').read_text(),'reference');assert set(sm['port_order'])==set(rm['port_order']);p=d/'gds_exact_native_v1.spice';q=d/'gds_exact_reference_v1.spice';assert not p.exists() and not q.exists();p.write_text(source.replace('.subckt '+top+' ','.subckt parent ',1));q.write_text(reference.replace('.subckt reference ','.subckt parent ',1));gp=d/'gds_exact_graph_v1.json';lp=d/'gds_exact_graph_v1.log';cmd=['docker','run','--rm','--network','none','--memory','2g','--cpus','2','--volume',f'{R}:/workspace','--workdir','/workspace','--entrypoint','timeout','eventspikeseg:torch2.2.2-cuda11.8','120','python','scripts/compare_gf180_exact_unique_net_bijection_v1.py','--source',p.relative_to(R).as_posix(),'--other',q.relative_to(R).as_posix(),'--report',gp.relative_to(R).as_posix()];run=subprocess.run(cmd,capture_output=True,text=True,timeout=135);lp.write_text(run.stdout+run.stderr);report=dict(cell=a.cell,independent_connectivity_and_dimensions_verified=run.returncode==0 and gp.exists(),primitive_count=sm['primitive_devices'],reference_primitives=rm['primitive_devices'],graph_returncode=run.returncode,native_netgen_property_errors_retained=True,scope='Exact primitive model,W/L/MIM dimension and pin/net/edge bijection vs independently composed child reference;native diffusion area/perimeter retained for simulation butnot dimension proof. Native Netgen matched topology with property warnings;do not call clean LVS.',graph_report=str(gp.relative_to(R)) if gp.exists() else None,sha256={str(z.relative_to(R)):hashlib.sha256(z.read_bytes()).hexdigest() for z in [Path(__file__),native,d/'reference.spice',p,q,lp]});dest.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
